import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long w = scanner.nextLong();
        long m = scanner.nextLong();

        long[] sum = new long[105];
        long[] pw = new long[105];
        boolean OK = false;

        long p = 1;
        int mx = 0;
        for (int i = 0; i < 100; i++) {
            sum[i + 1] = p + sum[i];
            pw[i] = p;
            p *= w;
            if (p > (1L << 40)) {
                mx = i;
                break;
            }
        }

        OK = false;
        process(0, m, mx, sum, pw, OK);
        System.out.println(OK ? "YES" : "NO");
    }

    static void process(long cur, long target, int pos, long[] sum, long[] pw, boolean OK) {
        if (OK) return;
        if (cur == target) {
            OK = true;
            return;
        }
        long remaining = sum[pos + 1];
        long next = pw[pos];

        if (cur - remaining > target) {
            return;
        } else if (cur + remaining < target) {
            return;
        } else {
            if (cur + sum[pos] < target) {
                process(cur + next, target, pos - 1, sum, pw, OK);
            } else if (cur - sum[pos] > target) {
                process(cur - next, target, pos - 1, sum, pw, OK);
            } else {
                process(cur, target, pos - 1, sum, pw, OK);
            }
        }
    }
}
